def evolved_p95(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # Formula: x[i] = (2 * i) % N  -- position-based
    idx = torch.arange(N, device=x.device).to(x.dtype)
    two_i = idx * 2.0
    return (two_i - (torch.div(two_i, N, rounding_mode='floor') * N)).contiguous().to(x.dtype)

def evolved_p95(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # Formula: x[i] = (2 * i) % N  -- position-based
    idx = torch.arange(N, device=x.device).to(x.dtype)
    return ((idx * 2.0) % N).contiguous().to(x.dtype)
